            archetypeBasicName: 'Basic',
            archetypeBasicTagline: 'Plain reading draft with scene opener pages.',
            archetypeStandardName: 'Standard',
            archetypeStandardTagline: 'Clean, modern reading draft with chapter breaks.',
            archetypeProfessionalName: 'Professional',
            archetypeProfessionalTagline: 'Refined typesetting with letter-spaced running heads.',
            archetypeSignatureName: 'Signature',
            archetypeSignatureTagline: 'Roman parts, numbered chapters, section breaks.',
            blurbSubmission: 'A plain reading draft on 6×9 pages, with sans-serif type, 1.5 line spacing, and separate scene openers. Customize its geometry and typography for your reader.',
            blurbReadingDraft: 'A polished reading draft for beta readers and proofers. Clean enough to feel like a finished book without committing to a final aesthetic. Contemporary serif body type, comfortable spacing, and restrained structure that stays familiar to modern commercial fiction.',
            blurbLiterary: 'Refined and publication-minded — the feel of a professionally typeset trade novel. Running heads, structured chapter presentation, and stronger visual rhythm create a more immersive reading experience while remaining restrained and highly readable.',
            blurbStructured: 'Architectural and literary. Built for ambitious fiction that benefits from deliberate pacing, structural breathing room, act openers, epigraphs, and distinctive scene presentation. Evokes the considered craftsmanship of boutique literary editions and mid-century print design traditions.',
            notePage: 'Page dimensions and margins shape the reading experience more than most authors realize. Tighter layouts increase density and pace, while wider margins create visual breathing room and a more literary feel. Most trade fiction balances readability with efficient page count.',
            noteBody: 'Body typography determines long-form reading comfort. Serif fonts remain dominant in printed fiction because they guide the eye naturally across dense pages of text. Line spacing subtly affects pacing: tighter layouts feel faster and more urgent, while open spacing slows the reader and creates reflection.',
            noteHeaders: 'Running headers help readers maintain orientation in longer works and are common in finished print editions. Draft manuscripts often omit them entirely, while polished trade and literary layouts frequently use restrained headers to reinforce structure without distracting from the prose.',
            noteFolio: 'Page numbers quietly anchor the reader inside the manuscript. Traditional drafts often place folios at the bottom center, while published fiction commonly integrates them into the running header system for a more refined presentation.',
            noteParts: 'Part pages divide major narrative movements and create structural breathing room between acts or phases of the story. Literary and large-scale commercial fiction often use dedicated Part openers, Roman numerals, or epigraphs to reinforce thematic transitions and long-form momentum.',
            noteChapters: 'Chapter presentation shapes narrative rhythm. Minimal chapter pages keep pacing invisible and fast, while larger openers create pause, emphasis, and anticipation. Shared chapter titles and opener spacing can subtly reinforce tone and genre expectations.',
            noteScenes: 'Scene breaks control momentum at the micro level. Invisible transitions create speed and continuity, while dedicated scene openers give emotional or structural weight to each sequence. Numbering, titles, and ornamental rules help readers orient themselves inside complex narratives.',
            noteEpigraph: 'Epigraphs frame the emotional or thematic lens of a section before the prose begins. Some novels use them sparingly for emphasis, while literary and structural fiction may use recurring epigraphs to create resonance across acts, chapters, or character arcs.',
            fontCustomSystem: 'Custom (system font)',
