            yamlStructureDescription: 'Base and property YAML sets are now cleanly separated. The base set defines core fields; the properties set adds optional fields. Commands and Book Designer now merge these automatically. Your field sets have been updated to the latest structure.',
            revisionToIterationTitle: 'YAML Field Update Required',
