            pendingEditsTypeTitle: 'YAML Type Change: Pending Edits & Summary Update',
            pendingEditsTypeDescription: '"Pending Edits" is no longer a boolean. It is now a string so it can act as both a yes/no flag and record the last AI API hit (timestamp and AI used). The YAML field "Summary Update" (formerly "Synopsis Update") works identically: string value with timestamp and AI used.',
            newFolderTitle: 'New Radial Timeline Folder',
            newFolderDescription: 'A new Radial Timeline folder has been created in your Obsidian vault to organize files under the updated structure, including AI API logs, Inquiry Briefs, Social APR exports and campaigns, and other related assets.',
            logFoldersTitle: 'Log folders reorganized',
            logFoldersDescription: 'Logs now live under Radial Timeline/Logs with dedicated folders for Inquiry, Gossamer, Pulse, Moves, Snapshots, and Gossamer Archive. Full AI content logs are stored inside Content subfolders for the matching feature.',
            recoveryFilesTitle: 'Recovery files moved out of Logs',
            recoveryFilesDescription: 'Snapshots and the Gossamer Archive — the files used to recover deleted or overwritten note data — now live under Radial Timeline/Recover instead of Radial Timeline/Logs. The Logs folder now holds only disposable run logs, so you can purge it at any time without losing recovery data. If a folder still exists at Radial Timeline/Logs/Snapshots or Radial Timeline/Logs/Gossamer Archive from before this update, move that specific folder into Radial Timeline/Recover to preserve the earlier recovery data. Warning: do NOT move Radial Timeline/Snapshots — that is a different, currently-live folder that Timeline Repair reads from to restore your timeline, and moving it will break that restore feature.',
            inquiryProButtonsTitle: 'Inquiry Pro buttons restyled',
